{"command":"# The kernel prevents reading /proc/pid/mem when executable is not readable (to prevent dumping). So we cannot dump binary easily.
# But we have other approaches: we can use ptrace? ptrace requires permission to trace, but same user may be able to ptrace? Let's try.
cat > /tmp/ptrace.c <<'EOS'
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdio.h>
int main(int argc,char**argv){
 pid_t pid=fork();
 if(pid==0){
   ptrace(PTRACE_TRACEME,0,0,0);
   execl(argv[1],argv[1],argv[2],NULL);
   perror("execl");
   return 1;
 } else {
   int status;
   waitpid(pid,&status,0);
   printf("traced %d status %d\n",pid,status);
   // detach
   ptrace(PTRACE_DETACH,pid,0,0);
 }
}
EOS
