cat > /tmp/myproj/Cargo.toml <<'EOS'
[package]
name = "executable"
version = "0.1.0"
edition = "2021"

[dependencies]
clap = { version = "4.6.1", features = [] }
clap_builder = { version = "4.6.0", features = [] }
tokio = { version = "1.52.3", features = ["full"] }
serde = { version = "1.0.228", features = ["derive"] }
