use clap_builder::{Command, Arg, value_parser, PossibleValue};
fn main() {
    let cmd = Command::new("executable")
        .subcommand(
            Command::new("server")
                .about("Run as a perf server")
                .arg(Arg::new("listen").long("listen").default_value("[::]:4433").help("Address to listen on"))
        )
        .subcommand(
            Command::new("client")
                .about("Run as a perf client")
                .arg(Arg::new("host").default_value("localhost:4433").help("Host to connect to"))
        );
    let m = cmd.get_matches();
    println!("{:?}", m.subcommand_name());
}
