fn run_client(matches: &clap::ArgMatches) {
    let host_str = matches.get_one::<String>("host").unwrap();
    let ip_override = matches.get_one::<IpAddr>("ip").cloned();
    let local_addr = matches.get_one::<SocketAddr>("local-addr").cloned();
    let uni_requests = *matches.get_one::<u64>("uni-requests").unwrap();
    let bi_requests = *matches.get_one::<u64>("bi-requests").unwrap();
    let download_size = *matches.get_one::<u64>("download-size").unwrap();
    let upload_size = *matches.get_one::<u64>("upload-size").unwrap();
    let duration = *matches.get_one::<u64>("duration").unwrap();
    let interval = *matches.get_one::<u64>("interval").unwrap();
    let json_path = matches.get_one::<String>("json").cloned();
    let send_buffer_size = *matches.get_one::<u64>("send-buffer-size").unwrap();
    let recv_buffer_size = *matches.get_one::<u64>("recv-buffer-size").unwrap();
    let conn_stats = matches.get_flag("conn-stats");
    let keylog = matches.get_flag("keylog");
    let initial_mtu = *matches.get_one::<u64>("initial-mtu").unwrap();
    let no_protection = matches.get_flag("no-protection");
    let initial_rtt = matches.get_one::<u64>("initial-rtt").cloned();
    let ack_frequency = matches.get_flag("ack-frequency");
    let congestion = matches.get_one::<String>("congestion").cloned();
    let stream_receive_window = matches.get_one::<u64>("stream-receive-window").cloned();
    let receive_window = matches.get_one::<u64>("receive-window").cloned();
    let send_window = matches.get_one::<u64>("send-window").cloned();
    let max_udp_payload_size = *matches.get_one::<u64>("max-udp-payload-size").unwrap();
    let qlog_path = matches.get_one::<String>("qlog").cloned();

    // Parse HOST
    let (host, port) = match parse_host(host_str) {
        Ok((h,p)) => (h,p),
        Err(e) => {
            log_error!("quinn_perf", "{}", e);
            std::process::exit(1);
        }
    };

    // Resolve
    let resolved = match resolve_host(&host, port, ip_override) {
        Ok(addr) => addr,
        Err(e) => {
            log_error!("quinn_perf", "{}", e);
            std::process::exit(1);
        }
    };

    // Logging similar to original
    // "connecting to {host} at {resolved}"
    // Host for log should be without port and without brackets? For original, when host is "example.com:14433", log shows "connecting to example.com at 104.20.23.154:14433" - host without port, without brackets.
    // For "127.0.0.1:14433", host is "127.0.0.1", log shows "connecting to 127.0.0.1 at 127.0.0.1:14433"
    // For "[::1]:14433", host would be "[::1]"? Let's clean brackets for log.
    let host_for_log = {
        let h = host.trim_matches(|c| c=='[' || c==']');
        h.to_string()
    };
    log_info!("perf::client", "connecting to {} at {}", host_for_log, resolved);

    if let Some(local) = local_addr {
        log_info!("perf::client", "local addr {}", local);
    } else {
        log_info!("perf::client", "local addr 0.0.0.0:0");
    }

    // Buffer size warnings similar to server
    #[cfg(unix)]
    {
        // Create a dummy UDP socket to check buffer sizes
        if let Ok(udp_socket) = std::net::UdpSocket::bind("0.0.0.0:0") {
            use std::os::unix::io::AsRawFd;
            let fd = udp_socket.as_raw_fd();
            unsafe {
                let desired_snd = send_buffer_size as libc::c_int;
                libc::setsockopt(fd, libc::SOL_SOCKET, libc::SO_SNDBUF, &desired_snd as *const _ as *const libc::c_void, std::mem::size_of::<libc::c_int>() as libc::socklen_t);
                let mut actual: libc::c_int = 0;
                let mut len = std::mem::size_of::<libc::c_int>() as libc::socklen_t;
                libc::getsockopt(fd, libc::SOL_SOCKET, libc::SO_SNDBUF, &mut actual as *mut _ as *mut libc::c_void, &mut len);
                let actual_u64 = actual as u64;
                if actual_u64 < send_buffer_size || actual_u64/2 < send_buffer_size {
