        if let Ok(mut f) = File::create(qlog_path) {
            let _ = writeln!(f, "{{\"qlog_version\":\"0.3\",\"qlog_format\":\"JSON-SEQ\",\"title\":\"perf-client\",\"trace\":{{\"vantage_point\":{{\"type\":\"unknown\"}},\"title\":\"perf-client\",\"configuration\":{{\"time_offset\":0.0}}}}}}");
        }
    }

