    // Worker threads for bi and uni
    // We'll spawn threads that loop for duration, performing requests.

    let total_requests = Arc::new(AtomicUsize::new(0));

    let duration_dur = Duration::from_secs(duration);

    // Function to perform one bidi request over TCP
    let perform_bidi = |stream_id: u64| -> RequestStats {
        let req_start = Instant::now();
        let upload_start = Instant::now();
        // Open TCP connection to resolved
        // We need to handle local_addr binding if specified
        let mut stream = match TcpStream::connect(resolved) {
            Ok(s) => s,
            Err(_) => {
                // For failure, return stats with error? We'll just return with zero durations
                // But we should log error "request failed: connection lost: closed"
                log_error!("perf::client", "request failed: connection lost: closed");
                // Return dummy stats
                return RequestStats {
                    id: stream_id,
