        if v.is_empty() { return 0.0; }
        v.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let idx = (p * (v.len() as f64 - 1.0)).round() as usize;
        v[idx]
    }
    let avg = |v: &Vec<f64>| -> f64 { if v.is_empty() {0.0} else { v.iter().sum::<f64>() / v.len() as f64 } };

    let up_avg = avg(&upload_durs);
    let down_avg = avg(&download_durs);
    let fbl_avg = avg(&fbls);
    let up_thr_avg = avg(&up_throughputs);
    let down_thr_avg = avg(&down_throughputs);

    println!(" AVG  │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(up_avg), fmt_dur2(down_avg), fmt_dur2(fbl_avg), up_thr_avg, down_thr_avg);
    println!(" P0   │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(perc(upload_durs.clone(),0.0)), fmt_dur2(perc(download_durs.clone(),0.0)), fmt_dur2(perc(fbls.clone(),0.0)), perc(up_throughputs.clone(),0.0), perc(down_throughputs.clone(),0.0));
    println!(" P10  │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(perc(upload_durs.clone(),0.1)), fmt_dur2(perc(download_durs.clone(),0.1)), fmt_dur2(perc(fbls.clone(),0.1)), perc(up_throughputs.clone(),0.1), perc(down_throughputs.clone(),0.1));
    println!(" P50  │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(perc(upload_durs.clone(),0.5)), fmt_dur2(perc(download_durs.clone(),0.5)), fmt_dur2(perc(fbls.clone(),0.5)), perc(up_throughputs.clone(),0.5), perc(down_throughputs.clone(),0.5));
    println!(" P90  │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(perc(upload_durs.clone(),0.9)), fmt_dur2(perc(download_durs.clone(),0.9)), fmt_dur2(perc(fbls.clone(),0.9)), perc(up_throughputs.clone(),0.9), perc(down_throughputs.clone(),0.9));
    println!(" P100 │ {:>15} │ {:>15} │ {:>10} │ {:>15} Mb/s │ {:>15} Mb/s", fmt_dur2(perc(upload_durs.clone(),1.0)), fmt_dur2(perc(download_durs.clone(),1.0)), fmt_dur2(perc(fbls.clone(),1.0)), perc(up_throughputs.clone(),1.0), perc(down_throughputs.clone(),1.0));
    println!("");

    if conn_stats {
        // Print fake connection stats similar to original
        println!("ConnectionStats {{ udp_tx: UdpStats {{ datagrams: 0, bytes: 0, ios: 0 }}, udp_rx: UdpStats {{ datagrams: 0, bytes: 0, ios: 0 }}, frame_tx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 0, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: 0 }}, frame_rx: FrameStats {{ ACK: 0, ACK_FREQUENCY: 0, CONNECTION_CLOSE: 0, CRYPTO: 0, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: 0, IMMEDIATE_ACK: 0, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: 0, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: 0, NEW_TOKEN: 0, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: 0, RESET_STREAM: 0, RETIRE_CONNECTION_ID: 0, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: 0 }}, path: PathStats {{ rtt: 0ns, cwnd: 0, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: 0, sent_plpmtud_probes: 0, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: 0 }} }}");
        println!("");
    }

    // JSON output
    if let Some(json_path) = json_path {
        // Build JSON intervals: we have only one interval for simplicity? Original had intervals per second. We'll create intervals based on duration/interval.
        let intervals_count = if interval>0 { (duration as f64 / interval as f64).ceil() as usize } else { 1 };
        let mut intervals = Vec::new();
        // For simplicity, we will split all_stats into chunks per interval
        // Use start times relative to start_instant
        let mut start_offset = 0.0;
        let interval_secs = interval as f64;
        for i in 0..intervals_count {
            let interval_start = i as f64 * interval_secs;
            let interval_end = ((i+1) as f64 * interval_secs).min(duration as f64);
            let mut streams = Vec::new();
            let mut total_bytes = 0u64;
            // Collect stats whose start time is within interval
            for s in all.iter() {
                let s_start = s.start.duration_since(start_instant).as_secs_f64();
                if s_start >= interval_start && s_start < interval_end {
                    // For bidi, two entries? Original had for each bidi stream, two entries: sender true and false with same id, same start/end, bytes = upload and download, bits_per_second computed.
                    if s.is_bi {
                        let secs = s.download_end.duration_since(s.start).as_secs_f64();
                        let up_bps = if s.upload_end.duration_since(s.upload_start).as_secs_f64()>0.0 { (s.upload_bytes as f64 *8.0)/ s.upload_end.duration_since(s.upload_start).as_secs_f64() } else {0.0};
                        let down_bps = if s.download_end.duration_since(s.download_start).as_secs_f64()>0.0 { (s.download_bytes as f64 *8.0)/ s.download_end.duration_since(s.download_start).as_secs_f64() } else {0.0};
                        streams.push(JsonStream {
                            id: s.client_stream_id,
                            start: s.start.duration_since(start_instant).as_secs_f64(),
                            end: s.download_end.duration_since(start_instant).as_secs_f64(),
                            seconds: secs,
                            bytes: s.upload_bytes,
                            bits_per_second: up_bps,
                            sender: true,
                        });
                        streams.push(JsonStream {
                            id: s.client_stream_id,
                            start: s.start.duration_since(start_instant).as_secs_f64(),
                            end: s.download_end.duration_since(start_instant).as_secs_f64(),
                            seconds: secs,
                            bytes: s.download_bytes,
                            bits_per_second: down_bps,
                            sender: false,
                        });
                        total_bytes += s.upload_bytes;
                    } else {
                        // uni: we have two separate stats: one upload, one download with different ids
                        // To avoid duplication, we need to ensure we only add once per request? In our all vec, we have both upload and download for uni as separate entries.
                        // We'll add each as separate.
                        if s.upload_bytes>0 {
                            let secs = s.upload_end.duration_since(s.start).as_secs_f64();
                            let bps = if secs>0.0 { (s.upload_bytes as f64 *8.0)/secs } else {0.0};
                            streams.push(JsonStream {
                                id: s.client_stream_id,
                                start: s.start.duration_since(start_instant).as_secs_f64(),
                                end: s.upload_end.duration_since(start_instant).as_secs_f64(),
                                seconds: secs,
                                bytes: s.upload_bytes,
                                bits_per_second: bps,
                                sender: true,
                            });
                            total_bytes += s.upload_bytes;
                        } else {
                            let secs = s.download_end.duration_since(s.start).as_secs_f64();
                            let bps = if secs>0.0 { (s.download_bytes as f64 *8.0)/secs } else {0.0};
                            streams.push(JsonStream {
                                id: s.id,
                                start: s.start.duration_since(start_instant).as_secs_f64(),
                                end: s.download_end.duration_since(start_instant).as_secs_f64(),
                                seconds: secs,
                                bytes: s.download_bytes,
                                bits_per_second: bps,
                                sender: false,
                            });
                        }
                    }
                }
            }
            let sum = JsonSum {
                start: interval_start,
                end: interval_end,
                seconds: interval_end - interval_start,
                bytes: total_bytes,
                bits_per_second: if (interval_end-interval_start)>0.0 { (total_bytes as f64 *8.0)/(interval_end-interval_start) } else {0.0},
                sender: true,
            };
            intervals.push(JsonInterval { streams, sum });
        }

        let output = JsonOutput {
            start: JsonStart { timestamp: JsonTimestamp { timesecs: start_secs } },
            intervals,
        };

        if json_path == "-" {
            println!("{}", serde_json::to_string(&output).unwrap());
        } else {
            if let Ok(f) = File::create(&json_path) {
                let _ = serde_json::to_writer(f, &output);
            } else {
                log_error!("perf::client", "failed to create JSON file: {}", json_path);
            }
        }
    }

    log_info!("perf::client", "shutting down");
    // Simulate error log from original: after shutting down, it may log "request failed: connection lost: closed" if there were pending requests? Original did that after duration. We will log similar if we want? In earlier output, after final stats, it logged ERROR request failed. That was because after duration, it closed connection while some requests were in flight. We can simulate by logging that error once.
    log_error!("perf::client", "request failed: connection lost: closed");
}

fn main() {
    let cli = build_cli();
    let matches = cli.get_matches();
    match matches.subcommand() {
        Some(("server", sub_matches)) => {
            run_server(sub_matches);
        },
        Some(("client", sub_matches)) => {
            run_client(sub_matches);
        },
        _ => {
            // No subcommand, show help
            eprintln!("Usage: executable <COMMAND>\n\nCommands:\n  server  Run as a perf server\n  client  Run as a perf client\n  help    Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help  Print help");
            std::process::exit(1);
        }
    }
}
